import itertools, sys, time, random, math
from z3 import *

# Parameters
G = 30  # golfers
W = 7   # weeks
S = 3   # group size
G_per_week = 10  # groups per week

# Variables: x[w][g][p] = 1 if golfer p is in group g in week w
x = [[[Bool(f'x_{w}_{g}_{p}') for p in range(G)] for g in range(G_per_week)] for w in range(W)]

s = Solver()

# Each golfer in exactly one group per week
for w in range(W):
    for p in range(G):
        s.add(PbEq([(x[w][g][p], 1) for g in range(G_per_week)], 1))

# Each group has exactly S golfers per week
for w in range(W):
    for g in range(G_per_week):
        s.add(PbEq([(x[w][g][p], 1) for p in range(G)], S))

# No pair of golfers appears together more than once
# For each pair (p1, p2), for each week w, they are together if they are in same group
# We'll create auxiliary variables for pair-week
pair_week = {}
for p1 in range(G):
    for p2 in range(p1+1, G):
        for w in range(W):
            # They are together in week w if there exists a group g where both are assigned
            together = Bool(f'together_{p1}_{p2}_{w}')
            # together = OR over g of (x[w][g][p1] and x[w][g][p2])
            s.add(together == Or([And(x[w][g][p1], x[w][g][p2]) for g in range(G_per_week)]))
            pair_week[(p1,p2,w)] = together

# At most one week per pair
for p1 in range(G):
    for p2 in range(p1+1, G):
        s.add(PbLe([(pair_week[(p1,p2,w)], 1) for w in range(W)], 1))

print("Solving...")
start = time.time()
res = s.check()
print(f"Result: {res}, time: {time.time()-start:.2f}s")

if res == sat:
    m = s.model()
    # Build solution
    sol = []
    for w in range(W):
        for p in range(G):
            for g in range(G_per_week):
                if is_true(m[x[w][g][p]]):
                    sol.append(g)
                    break
    print("Solution found:", sol[:30], "...")
    print("Length:", len(sol))
    # Verify
    # Check no pair appears twice
    from collections import defaultdict
    pair_counts = defaultdict(int)
    for w in range(W):
        groups = [[] for _ in range(G_per_week)]
        for p in range(G):
            g = sol[w*G + p]
            groups[g].append(p)
        for g in range(G_per_week):
            for i in range(len(groups[g])):
                for j in range(i+1, len(groups[g])):
                    p1, p2 = groups[g][i], groups[g][j]
                    if p1 > p2:
                        p1, p2 = p2, p1
                    pair_counts[(p1,p2)] += 1
    max_pair = max(pair_counts.values())
    print(f"Max pair count: {max_pair}")
    print(f"All pairs <= 1: {max_pair <= 1}")
else:
    print("UNSAT")

